#!/bin/bash
set -e
DEST="comet-enhanced-deploy-install"
rm -rf "$DEST"
mkdir -p "$DEST/.opencode/"{skills,commands}
echo "comet-enhanced 一键部署"
decode_mode=0; current_path=""; current_data=""
while IFS= read -r line; do
  [ "$decode_mode" = "0" ] && { [ "$line" = "### BEGIN DATA" ] && decode_mode=1; continue; }
  [ "$line" = "### PATH" ] && { decode_mode=2; continue; }
  [ "$decode_mode" = "2" ] && { current_path="$line"; current_data=""; decode_mode=3; continue; }
  if [ "$line" = "### END FILE" ]; then
    mkdir -p "$DEST/$(dirname "$current_path")"
    printf '%s' "$current_data" | base64 -d > "$DEST/$current_path"
    current_data=""; decode_mode=1; continue
  fi
  [ "$decode_mode" = "3" ] && current_data="${current_data}${line}"
done < "$0"
ln -sf .opencode/skills/comet-enhanced "$DEST/comet-enhanced"
echo "  部署完成: $DEST ($(find "$DEST/.opencode" -type f | wc -l) skill files)"
exit 0
